N.forEach(n=>{const d=document.createElement('div');d.className='nd';d.dataset.id=n.id;d.dataset.cmp='';d.dataset.live='';d.tabIndex=0;d.setAttribute('role','button');d.setAttribute('aria-label',n.t);d.addEventListener('keydown',e=>{if(e.target===d&&(e.key==='Enter'||e.key===' ')){e.preventDefault();UX.focus(d)}});d.style.cssText=`left:${n.x}px;top:${n.y}px`;d.innerHTML=`<div class="nd-t"><span>${n.t}</span><span class="faint" data-tool>···</span></div><div class="pic" style="background:var(--w${n.p}) center/cover"></div><div class="xs mute" style="margin-top:calc(6px*var(--y))">1920 × 1080</div><span class="port in"></span><span class="port out"></span>`;world.append(d);
 d.addEventListener('pointerdown',e=>{if(e.button!==0)return;delete d.dataset.dragged;const sx=e.clientX,sy=e.clientY,ox=n.x,oy=n.y;let moved=false;d.setPointerCapture(e.pointerId);d.classList.add('drag');const mv=ev=>{if(ev.pointerId!==e.pointerId)return;moved=moved||Math.hypot(ev.clientX-sx,ev.clientY-sy)>4;n.x=ox+(ev.clientX-sx)/cv.scale();n.y=oy+(ev.clientY-sy)/cv.scale();d.style.left=n.x+'px';d.style.top=n.y+'px';wires()};const end=ev=>{if(ev.pointerId!==e.pointerId)return;if(ev.type==='pointercancel'){n.x=ox;n.y=oy;d.style.left=ox+'px';d.style.top=oy+'px';wires()}d.classList.remove('drag');d.removeEventListener('pointermove',mv);d.removeEventListener('pointerup',end);d.removeEventListener('pointercancel',end);d.removeEventListener('lostpointercapture',end);if(d.hasPointerCapture(e.pointerId))d.releasePointerCapture(e.pointerId);if(moved)d.dataset.dragged='true'};d.addEventListener('pointermove',mv);d.addEventListener('pointerup',end);d.addEventListener('pointercancel',end);d.addEventListener('lostpointercapture',end)})});
